// =============================================================================
// operator-inputs.mjs — the ONE canonical schema of operator-supplied inputs
// =============================================================================
// The single source of truth for the SMALL set of values an operator must
// supply to stand up (or fork) an AISHA instance — everything a fork cannot
// DERIVE. Every stack-internal secret and every derived domain/mesh/URL is
// generated by scripts/generate-secrets.mjs + derive-domains and MUST NOT
// appear here.
//
// NOTHING provider- or model-specific is hardcoded here. The credential / BYOK
// inputs (LLM providers, mesh, email, observability, infra tokens, …) are
// PARSED at load time from config/external-secrets.required.env — the
// @-annotated source of truth that file itself designates for wizard use
// ("Parser čte @-annotated komentáře pro každý klíč"). Add a provider there,
// annotate it, and it flows into every consumer automatically; the runtime
// dynamic catalog is ai_provider_registry. This module only ADDS the non-secret
// topology / identity decisions (TLDs, namespace, admin, overlay) that are raw
// per-instance choices and live in no other SoT.
//
// Consumed by (fix-at-source — no drift between prompt, doc, and reality):
//   • scripts/operator-setup.mjs   — interactive local install/verify workbench
//   • config/fork-instance-inputs.env.example — GENERATED from this schema
//   • scripts/aisha-cold-start.sh  — prompts for the missing REQUIRED inputs
//   • the IDE add-on / a web workbench — via `operator-setup.mjs --json`
// =============================================================================
import { readFileSync, existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const SECRETS_FILE = resolve(HERE, "../../config/external-secrets.required.env");

