const NON_SECRET_CATEGORIES = {
  "infra-endpoints": "Infra endpoints — where your Coolify / Forgejo live (the URLs; matching tokens are secrets, below)",
  topology: "Topology — the instance's public shape: its 3 TLDs, namespace, admin, and where it deploys",
  identity: "Instance identity — which content/users/overlay make this instance itself (the private overlay repo)",
};

function slugifyCategory(header) {
  return header
    .replace(/\(.*$/, "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/** Human label from a KEY (e.g. SOME_API_KEY → "Some API Key"). */
function labelFromKey(key) {
  return key
    .toLowerCase()
    .split("_")
    .map((w) => (w === "api" || w === "id" || w === "url" || w === "dsn" ? w.toUpperCase() : w.charAt(0).toUpperCase() + w.slice(1)))
    .join(" ");
}

/**
 * Parse config/external-secrets.required.env — the @-annotated SoT — into secret
 * inputs. Category comes from the `# CATEGORY:` headers; required/description/
 * source/degraded from the @annotations. Keys annotated `@generated true`
 * (regenerated by cold-start or filled by a tool post-deploy) are NOT operator
 * inputs and are skipped. Nothing here names a provider — the file does.
 */
export function parseExternalSecrets(file = SECRETS_FILE) {
  const inputs = [];
  const categories = {};
  if (!existsSync(file)) return { inputs, categories };
  let category = "external";
  let categoryHeader = "External credentials";
  let ann = {};
  for (const raw of readFileSync(file, "utf8").split(/\r?\n/)) {
    const line = raw.trim();
    const cat = line.match(/^#\s*CATEGORY:\s*(.+)$/i);
    if (cat) {
      categoryHeader = cat[1].trim();
      category = slugifyCategory(categoryHeader) || "external";
      // Registered only when it actually yields a non-generated input (below),
      // so an all-@generated category doesn't surface as an empty group.
      continue;
    }
    const at = line.match(/^#\s*@(\w+)\s*(.*)$/);
    if (at) {
      ann[at[1].toLowerCase()] = at[2].trim();
      continue;
    }
    const kv = line.match(/^([A-Z][A-Z0-9_]*)=/);
    if (kv) {
      const key = kv[1];
      const generated = /^true\b/i.test(ann.generated || "");
      if (!generated) {
        inputs.push({
          key,
          category,
          label: labelFromKey(key),
          description: ann.purpose || `${labelFromKey(key)} (external credential).`,
          required: /^true\b/i.test(ann.required || ""),
          secret: true,
          example: "", // secret — supply the real value out of band; never a placeholder token
          source: ann.source || undefined,
          degraded: ann.degraded || undefined,
          critical: ann.critical || undefined,
        });
        if (!categories[category]) categories[category] = categoryHeader;
      }
      ann = {};
      continue;
    }
    if (line === "") ann = {}; // blank line ends an annotation block with no key
  }
  return { inputs, categories };
}

const EXTERNAL = parseExternalSecrets();

/** All operator inputs: non-secret topology/identity + parsed external secrets. */
export const OPERATOR_INPUTS = [...NON_SECRET_INPUTS, ...EXTERNAL.inputs];

/** Category descriptions (non-secret static + secret categories from the file). */
export const CATEGORIES = { ...NON_SECRET_CATEGORIES, ...EXTERNAL.categories };

/** All required inputs (the instance can't come up without these). */
export function requiredInputs() {
  return OPERATOR_INPUTS.filter((i) => i.required);
}

/** Inputs grouped by category, in CATEGORIES order. */
export function byCategory() {
  const groups = {};
  for (const cat of Object.keys(CATEGORIES)) groups[cat] = [];
  for (const input of OPERATOR_INPUTS) (groups[input.category] ??= []).push(input);
  return groups;
}

/** Machine-readable contract for the IDE add-on / web workbench. */
export function toJson() {
  return { categories: CATEGORIES, inputs: OPERATOR_INPUTS };
}

/** Render the canonical config/fork-instance-inputs.env.example text. */
export function renderEnvExample() {
  const lines = [
    "# =============================================================================",
    "# fork-instance-inputs.env.example — the MINIMAL operator input set",
    "# =============================================================================",
    "# GENERATED from scripts/lib/operator-inputs.mjs — DO NOT EDIT BY HAND.",
    "# Regenerate: node scripts/operator-setup.mjs --print-env-example > config/fork-instance-inputs.env.example",
    "#",
    "# Non-secret topology/identity is declared in operator-inputs.mjs; the secret",
    "# credentials below are PARSED from config/external-secrets.required.env (its",
    "# @annotations), so providers are never hardcoded twice.",
    "#",
    "# Copy the values you need into .env.local (gitignored) or your environment,",
    "# then run:  node scripts/operator-setup.mjs   (interactive setup + local verify).",
    "# Every secret and every domain the stack needs to run ITSELF is generated/derived.",
    "# =============================================================================",
    "",
  ];
  const groups = byCategory();
  for (const [cat, meta] of Object.entries(CATEGORIES)) {
    const inputs = groups[cat];
    if (!inputs?.length) continue;
    lines.push(`# ── ${meta}`);
    for (const i of inputs) {
      const tags = [
        i.required ? "REQUIRED" : "optional",
        i.secret ? "secret" : null,
        i.file ? "file" : null,
      ].filter(Boolean);
      lines.push(`# ${i.label} [${tags.join(", ")}] — ${i.description}`);
      if (i.source) lines.push(`#   get it: ${i.source}`);
      if (i.degraded) lines.push(`#   without it: ${i.degraded}`);
      if (i.derive) lines.push(`#   default: ${i.derive}`);
      if (i.file) {
        lines.push(`#   ${i.key} — see ${i.example}`);
      } else if (i.secret) {
        lines.push(`${i.key}=`);
      } else {
        lines.push(`${i.key}=${i.example}`);
      }
      lines.push("");
    }
  }
  return lines.join("\n").replace(/\n{3,}/g, "\n\n").trimEnd() + "\n";
}
